#include <Wire.h>
#include <LiquidCrystal_I2C.h>

// Create LCD object at 7-bit hex address 0x27 (16 columns, 2 rows)
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  lcd.init();          // Initialize LCD hardware and I2C bus
  lcd.backlight();     // Turn on backlight LED
  lcd.setCursor(0, 0); // Column 0, Row 0
  lcd.print("Monster Online!");
}

void loop() {
  // Static display
}
